// Place value in a four-digit number, drawn to scale: the widths of the
// blocks are proportional to the values they stand for.
//
// size(W,H) bounds the output under Asymptote's default keepAspect and does not
// scale labels, so the compiler decides the box. This declaration is restated from
// a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(320,200);
filldraw((0,0)--(10,80)--(10,0)--cycle,lightgray);
filldraw((10,0)--(110,80)--(10,80)--cycle,gray);
filldraw((110,0)--(185,80)--(110,80)--cycle,lightgray);
filldraw((185,0)--(200,80)--(185,80)--cycle,black);
label("$1$",(5,44),E);
label("$10$",(60,44),E);
label("$100$",(147,44),E);
label("$1000$",(192,44),W);
label("each block is ten times the width of the one before it",(100,120),N);

// Casting out nines: the digit sums of two numbers that agree modulo 9.
//
// size(W,H) bounds the output under Asymptote's default keepAspect and does not
// scale labels, so the compiler decides the box. This declaration is restated from
// a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(320,240);
label("$1782$",(0,0),W);
label("$2451$",(0,-1),W);
label("digit sum $18$",(3.2,0),W);
label("digit sum $12$",(3.2,-1),W);
draw((0,0.4)--(5.6,0.4));
draw((0,-0.6)--(4.0,-0.6));
label("$1782 - 2451 = -669 = -74 \\cdot 9$",(2.8,1.2),N);

// The last-digit cycle of powers of 3, drawn as a closed loop of four states.
//
// size(W,H) bounds the output under Asymptote's default keepAspect and does not
// scale labels, so the compiler decides the box. This declaration is restated from
// a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(320,220);
dot((0,0), black+4pt);
dot((120,0), black+4pt);
dot((120,110), black+4pt);
dot((0,110), black+4pt);
draw((6,2)--(112,2),Arrow);
draw((122,6)--(122,102),Arrow);
draw((114,108)--(8,108),Arrow);
draw((-2,104)--(-2,8),Arrow);
label("$3$",(0,14),N);
label("$9$",(120,14),N);
label("$7$",(120,92),S);
label("$1$",(0,92),S);
label("the cycle repeats with period four",(60,150),N);
